  split_props = c(train = 0.60, val = 0.20, test = 0.20),
  cv_folds = 5,
  bad_quantile = 0.15,
  # Common class-imbalance treatment (see Section 3): "balanced" or "none".
  # "none" makes the RBF SVM degenerate (near-constant decision values) when
  # the signal is weak, e.g. the GPM x AssetTurn two-predictor model.
  class_weighting = "balanced",
  # Grids are ordered simplest-first so which.max() breaks ties toward
  # the simpler model.
  grid_cart = data.frame(
    cp = c(0.032, 0.016, 0.008, 0.004, 0.002, 0.001, 0.0005)
  ),
  grid_knn = data.frame(k = c(301, 201, 151, 101, 75, 51, 35, 21, 11, 5)),
  # kernlab rbfdot: K(x, x') = exp(-sigma * ||x - x'||^2), with
  # sigma = sigma_mult / p (p = number of scaled inputs), so the grid adapts
  # to 24 inputs (ratios + Sector), 15 (ratios only) or 2 (boundary plots).
  # sigma_mult ~ 0.5 is the usual 1/(2p) scale; small sigma with large C
  # approaches a linear boundary, so the grid spans both regimes.
  grid_svm = expand.grid(
    C = c(0.25, 1, 4, 16, 64),
    sigma_mult = c(0.005, 0.0125, 0.025, 0.06, 0.12, 0.25, 0.5, 1)
  )
)

