derive_target <- function(growth, q = cfg$bad_quantile) {
  as.integer(growth <= quantile(growth, probs = q))
}

# Regenerate the seed-2026 DGP in quiet mode (no printing, no file writes).
regenerate_dgp <- function(seed, n = 3000) {
  old <- options(
    mlff.sim_quiet = TRUE,
    mlff.sim_seed = seed,
    mlff.n_companies = n
  )
  on.exit(options(old))
  env <- new.env()
  suppressMessages(source(dgp_script, local = env))
  env
}

