# Oracle-knowledge bundle for engineered features and true-boundary plots
make_eng <- function(truth) {
  list(center = truth$center, scale = truth$scale, params = truth$params)
}

## -----------------------------------------------------------------------
## 2. Helper functions: partitions, preprocessing, metrics
## -----------------------------------------------------------------------

split_strat <- function(y, props, seed) {
  set.seed(seed)
  out <- character(length(y))
  for (cls in unique(y)) {
    idx <- which(y == cls)
    idx <- idx[sample.int(length(idx))]
    n <- length(idx)
    n_tr <- round(props[["train"]] * n)
    n_va <- round(props[["val"]] * n)
    out[idx[seq_len(n_tr)]] <- "train"
    out[idx[n_tr + seq_len(n_va)]] <- "val"
    out[idx[(n_tr + n_va + 1):n]] <- "test"
  }
  out
}

cv_folds_strat <- function(y, k, seed) {
  set.seed(seed)
  f <- integer(length(y))
  for (cls in unique(y)) {
    idx <- which(y == cls)
    f[idx] <- sample(rep_len(seq_len(k), length(idx)))
  }
  f
}

# Engineered features use the TRUE functional forms and knots (oracle
# knowledge); their coefficients are still estimated by logistic regression.
eng_features <- function(X, eng) {
  z <- function(v) (X[, v] - eng$center[[v]]) / eng$scale[[v]]
  p <- eng$params
  cap <- p$interaction_cap
  h <- pmax(0, z("EV_EBITDA") - p$ev_threshold_z)
  cbind(
    eng_opm_below = as.numeric(z("OpMargin") < p$opm_threshold_z),
    eng_gpm_x_at = cap *
      tanh(z("GPM") / cap) *
      cap *
      tanh(z("AssetTurn") / cap),
    eng_ev_hinge = p$ev_saturation * tanh(h^2 / p$ev_saturation)
  )
}

prep_design <- function(pp, df) {
  X <- as.matrix(df[pp$num_vars])
  for (j in seq_along(pp$num_vars)) {
    X[is.na(X[, j]), j] <- pp$med[[j]]
  }
  if (!is.null(pp$eng)) {
    X <- cbind(X, eng_features(X, pp$eng))
  }
  if (!is.null(pp$sec_levels)) {
    if (!all(df$Sector %in% pp$sec_levels)) {
      stop("Sector level not seen in training data.", call. = FALSE)
    }
    D <- outer(df$Sector, pp$sec_levels[-1], "==") * 1
    colnames(D) <- make.names(paste0("Sector_", pp$sec_levels[-1]))
    X <- cbind(X, D)
  }
  X
}

prep_fit <- function(df, num_vars, use_sector, eng = NULL) {
  pp <- list(
    num_vars = num_vars,
    med = vapply(df[num_vars], \(x) median(x, na.rm = TRUE), numeric(1)),
    sec_levels = if (use_sector) sort(unique(df$Sector)) else NULL,
    eng = eng
  )
  M <- prep_design(pp, df)
  pp$mu <- colMeans(M)
  pp$sd <- apply(M, 2, sd)
  pp$sd[pp$sd == 0] <- 1
  pp
}

prep_apply <- function(pp, df) {
  M <- prep_design(pp, df)
  sweep(sweep(M, 2, pp$mu), 2, pp$sd, "/")
}

auc_rank <- function(score, y) {
  r <- rank(score)
  n1 <- sum(y == 1)
  n0 <- sum(y == 0)
  (sum(r[y == 1]) - n1 * (n1 + 1) / 2) / (n1 * n0)
}

# Average precision (step-wise PR AUC), tie groups handled as one threshold.
pr_auc_ap <- function(score, y) {
  o <- order(score, decreasing = TRUE)
  s <- score[o]
  yy <- y[o]
  last <- c(s[-1] != s[-length(s)], TRUE)
  tp <- cumsum(yy)[last]
  fp <- cumsum(1 - yy)[last]
  sum(diff(c(0, tp / sum(yy))) * tp / (tp + fp))
}

# Youden-optimal threshold: predict Bad if score >= threshold.
youden_threshold <- function(score, y) {
  o <- order(score, decreasing = TRUE)
  s <- score[o]
  yy <- y[o]
  last <- c(s[-1] != s[-length(s)], TRUE)
  J <- cumsum(yy)[last] / sum(yy) - cumsum(1 - yy)[last] / sum(1 - yy)
  s[last][which.max(J)]
}

class_metrics <- function(score, y, thr) {
  pred <- as.integer(score >= thr)
  tp <- sum(pred == 1 & y == 1)
  fp <- sum(pred == 1 & y == 0)
  fn <- sum(pred == 0 & y == 1)
  tn <- sum(pred == 0 & y == 0)
  tibble(
    roc_auc = auc_rank(score, y),
    pr_auc = pr_auc_ap(score, y),
    sensitivity = tp / (tp + fn),
    specificity = tn / (tn + fp),
    precision = if (tp + fp > 0) tp / (tp + fp) else NA_real_,
    f1 = 2 * tp / (2 * tp + fp + fn)
  )
}

## -----------------------------------------------------------------------
## 3. Model fitting, scoring and tuning
## -----------------------------------------------------------------------
## Every scorer returns "higher = more likely Bad_Earnings".

## Class weighting (cfg$class_weighting):
##   "balanced": each class carries equal total weight (w = n / (2 * n_class)).
##     logistic -> case weights; CART -> equal class priors; SVM -> class
##     weights. kNN has no weights: class-weighted voting is a monotone
##     transform of the neighbor Bad share, so its ranking (AUC) is identical
##     and the validation-selected threshold absorbs the rescaling.
##   "none": unweighted fits for every method.

fit_model <- function(method, X, y, hp, weighting = cfg$class_weighting) {
  balanced <- identical(weighting, "balanced")
  n1 <- sum(y == 1)
  n0 <- sum(y == 0)
  switch(
    method,
    logit = {
      w <- if (balanced) {
        ifelse(y == 1, length(y) / (2 * n1), length(y) / (2 * n0))
      } else {
        rep(1, length(y))
      }
      # suppressWarnings: non-integer binomial weights trigger a benign
      # warning; convergence is checked via fit$converged instead.
      fit <- suppressWarnings(glm.fit(
        cbind(1, X),
        y,
        weights = w,
        family = binomial()
      ))
      b <- fit$coefficients
      b[is.na(b)] <- 0
      list(b = b, converged = fit$converged)
    },
    cart = rpart::rpart(
      y ~ .,
      data = data.frame(y = factor(y, levels = c(0, 1)), X),
      method = "class",
      parms = if (balanced) list(prior = c(0.5, 0.5)) else list(),
      control = rpart::rpart.control(
        cp = hp$cp,
        minsplit = 20,
        minbucket = 7,
        xval = 0,
        maxcompete = 0,
        maxsurrogate = 0
      )
    ),
    knn = caret::knn3(X, factor(y, levels = c(0, 1)), k = hp$k),
    svm = {
      fit <- kernlab::ksvm(
        X,
        factor(y, levels = c(0, 1)),
        type = "C-svc",
        kernel = "rbfdot",
        kpar = list(sigma = hp$sigma_mult / ncol(X)),
        C = hp$C,
        scaled = FALSE,
        prob.model = FALSE,
        class.weights = if (balanced) {
          c("0" = length(y) / (2 * n0), "1" = length(y) / (2 * n1))
        } else {
          NULL
        }
      )
      # Orient decision values on TRAINING data so that higher = Bad.
      dv <- as.numeric(kernlab::predict(fit, X, type = "decision"))
      list(fit = fit, sgn = if (mean(dv[y == 1]) >= mean(dv[y == 0])) 1 else -1)
    },
    stop("Unknown method: ", method)
  )
}

score_model <- function(method, fit, X) {
  switch(
    method,
    logit = drop(cbind(1, X) %*% fit$b),
    cart = predict(fit, data.frame(X), type = "prob")[, "1"],
    knn = predict(fit, X, type = "prob")[, "1"],
    svm = fit$sgn *
      as.numeric(kernlab::predict(fit$fit, X, type = "decision"))
  )
}

tune_model <- function(method, df_tr, y_tr, folds, grid, prep_args) {
  K <- max(folds)
  auc <- matrix(NA_real_, nrow(grid), K)
  for (k in seq_len(K)) {
    a <- folds != k
    pp <- do.call(prep_fit, c(list(df = df_tr[a, ]), prep_args))
    Xa <- prep_apply(pp, df_tr[a, ])
    Xb <- prep_apply(pp, df_tr[!a, ])
    for (g in seq_len(nrow(grid))) {
      fit <- fit_model(method, Xa, y_tr[a], as.list(grid[g, , drop = FALSE]))
      auc[g, k] <- auc_rank(score_model(method, fit, Xb), y_tr[!a])
    }
  }
  hp_names <- names(grid)
  grid$cv_auc <- rowMeans(auc)
  grid$cv_se <- apply(auc, 1, sd) / sqrt(K)
  best <- as.list(grid[which.max(grid$cv_auc), hp_names, drop = FALSE])
  list(best = best, grid = grid)
}

## -----------------------------------------------------------------------
## 4. One replicate: partition -> tune (CV in train) -> threshold (val) -> test
## -----------------------------------------------------------------------

run_replicate <- function(
  df,
  y,
  oracle_score,
  split_seed,
  cfg,
  eng,
  methods = c("logit", "logit_eng", "cart", "knn", "svm", "oracle"),
  num_vars = cfg$num_vars,
  use_sector = cfg$use_sector,
  keep_models = FALSE
) {
  part <- split_strat(y, cfg$split_props, split_seed)
  tr <- part == "train"
  va <- part == "val"
  te <- part == "test"
  folds <- cv_folds_strat(y[tr], cfg$cv_folds, split_seed + 1)

  prep_base <- list(num_vars = num_vars, use_sector = use_sector, eng = NULL)
  prep_eng <- list(num_vars = num_vars, use_sector = use_sector, eng = eng)
  specs <- list(
    logit = list(method = "logit", prep = prep_base, grid = NULL),
    logit_eng = list(method = "logit", prep = prep_eng, grid = NULL),
    cart = list(method = "cart", prep = prep_base, grid = cfg$grid_cart),
    knn = list(method = "knn", prep = prep_base, grid = cfg$grid_knn),
    svm = list(method = "svm", prep = prep_base, grid = cfg$grid_svm)
  )

  metrics <- list()
  tuning <- list()
  models <- list()
  for (m in setdiff(methods, "oracle")) {
    sp <- specs[[m]]
    hp <- list()
    if (!is.null(sp$grid)) {
      tuned <- tune_model(sp$method, df[tr, ], y[tr], folds, sp$grid, sp$prep)
      hp <- tuned$best
      tuning[[m]] <- tibble(
        model = m,
        hyperparameters = paste(
          names(hp),
          unlist(hp),
          sep = "=",
          collapse = ", "
        ),
        cv_auc = max(tuned$grid$cv_auc)
      )
    }
    pp <- do.call(prep_fit, c(list(df = df[tr, ]), sp$prep))
    fit <- fit_model(sp$method, prep_apply(pp, df[tr, ]), y[tr], hp)
    s_va <- score_model(sp$method, fit, prep_apply(pp, df[va, ]))
    s_te <- score_model(sp$method, fit, prep_apply(pp, df[te, ]))
    thr <- youden_threshold(s_va, y[va])
    metrics[[m]] <- class_metrics(s_te, y[te], thr) |>
      mutate(model = m, .before = 1)
    if (keep_models) {
      models[[m]] <- list(
        method = sp$method,
        fit = fit,
        pp = pp,
        thr = thr,
        hp = hp
      )
    }
  }
  if ("oracle" %in% methods) {
    thr <- youden_threshold(oracle_score[va], y[va])
    metrics$oracle <- class_metrics(oracle_score[te], y[te], thr) |>
      mutate(model = "oracle", .before = 1)
    if (keep_models) models$oracle <- list(thr = thr)
  }

  out <- list(
    metrics = bind_rows(metrics) |> mutate(split_seed = split_seed),
    tuning = bind_rows(tuning) |> mutate(split_seed = split_seed)
  )
  if (keep_models) {
    out$models <- models
    out$partition <- part
  }
  out
}

