## -----------------------------------------------------------------------
## 7. Independent datasets from other simulation seeds
## -----------------------------------------------------------------------
## Each seed regenerates the full DGP (new firms, ratios, noise, missingness).
## The student-style target is re-derived from that dataset's growth.

make_sim_set <- function(s, n = 3000) {
  env <- regenerate_dgp(s, n)
  list(
    seed = s,
    df = env$earnings_ratio_data,
    y = derive_target(env$earnings_ratio_data$Quarterly_Earnings_Growth),
    oracle = -env$dgp_truth$components$signal,
    eng = make_eng(env$dgp_truth)
  )
}
sim_sets <- lapply(sim_seeds, make_sim_set)

t_seed <- system.time({
  rep_seeds <- parLapply(
    cl,
    sim_sets,
    function(d, split_seed) {
      r <- run_replicate(d$df, d$y, d$oracle, split_seed, cfg, d$eng)
      r$metrics$sim_seed <- d$seed
      r$tuning$sim_seed <- d$seed
      r
    },
    split_seed = primary_split_seed
  )
})
metrics_seeds <- bind_rows(lapply(rep_seeds, `[[`, "metrics"))
tuning_seeds <- bind_rows(lapply(rep_seeds, `[[`, "tuning"))

## -----------------------------------------------------------------------
## 7b. Sensitivity: input dimensionality and sample size
## -----------------------------------------------------------------------
## Same protocol, same seeds. "No Sector" removes 9 dummy columns that carry
## no direct signal in the DGP (sector matters only through the ratios);
## larger n shows how much of the oracle gap flexible learners recover as
## estimation variance falls. Neither changes the course dataset.

t_sens <- c(elapsed = 0)
metrics_sens <- NULL
tuning_sens <- NULL
if (run_sensitivity) {
  sens_tasks <- list()
  # Largest designs first so load balancing finishes sooner
  for (i in order(sens_designs$n, decreasing = TRUE)) {
    for (s in sim_seeds[seq_len(sens_designs$n_seeds[i])]) {
      d <- if (sens_designs$n[i] == 3000) {
        sim_sets[[match(s, sim_seeds)]]
      } else {
        make_sim_set(s, sens_designs$n[i])
      }
      d$design <- sens_designs$design[i]
      d$use_sector <- sens_designs$use_sector[i]
      sens_tasks <- c(sens_tasks, list(d))
    }
  }
  t_sens <- system.time({
    rep_sens <- parLapplyLB(
      cl,
      sens_tasks,
      function(d, split_seed) {
        r <- run_replicate(
          d$df,
          d$y,
          d$oracle,
          split_seed,
          cfg,
          d$eng,
          use_sector = d$use_sector
        )
        r$metrics$sim_seed <- d$seed
        r$metrics$design <- d$design
        r$tuning$sim_seed <- d$seed
        r$tuning$design <- d$design
        r
      },
      split_seed = primary_split_seed
    )
  })
  metrics_sens <- bind_rows(lapply(rep_sens, `[[`, "metrics"))
  tuning_sens <- bind_rows(lapply(rep_sens, `[[`, "tuning"))
  rm(sens_tasks)
} else if (file.exists(file.path(diag_dir, "clf_metrics_sensitivity.csv"))) {
  metrics_sens <- read.csv(file.path(diag_dir, "clf_metrics_sensitivity.csv"))
  message(
    "Sensitivity results loaded from a previous run (run_sensitivity = FALSE)."
  )
}

