metric_names <- c(
  "roc_auc",
  "pr_auc",
  "sensitivity",
  "specificity",
  "precision",
  "f1"
)

summarise_metrics <- function(m, design) {
  m |>
    pivot_longer(all_of(metric_names), names_to = "metric") |>
    group_by(model, metric) |>
    summarise(mean = mean(value), sd = sd(value), .groups = "drop") |>
    mutate(design = design)
}

# Paired differences vs the additive logistic model, replicate by replicate.
# For repeated partitions of ONE dataset the replicates share data, so their
# spread understates sampling uncertainty; independent seeds do not.
paired_vs_logit <- function(m, id_col, design) {
  m |>
    select(all_of(id_col), model, roc_auc, pr_auc) |>
    pivot_longer(c(roc_auc, pr_auc), names_to = "metric") |>
    group_by(across(all_of(c(id_col, "metric")))) |>
    mutate(diff = value - value[model == "logit"]) |>
    ungroup() |>
    filter(model != "logit") |>
    group_by(model, metric) |>
    summarise(
      mean_diff = mean(diff),
      sd_diff = sd(diff),
      se_diff = sd(diff) / sqrt(n()),
      share_better = mean(diff > 0),
      n = n(),
      .groups = "drop"
    ) |>
    mutate(design = design)
}

