## -----------------------------------------------------------------------
## 9. Two-dimensional decision-boundary diagnostics
## -----------------------------------------------------------------------
## (A) Models trained on ONLY the two displayed predictors: the plotted
##     region is the model's complete decision rule.
## (B) Models trained on ALL 15 ratios + Sector (primary partition): the
##     plotted region is a 2-D SLICE with every other predictor held at its
##     training median (Sector = modal training sector). Because predictors
##     are correlated, many slice points are atypical firms; slices show how
##     each model *represents* the two inputs, not its overall accuracy.
## Each model is classified at its own validation-selected threshold.

grid_n <- 150
part1 <- primary$partition
train_df <- course_data[part1 == "train", ]

make_grid <- function(pair, base_df, n = grid_n) {
  r1 <- quantile(base_df[[pair[1]]], c(0.01, 0.99), na.rm = TRUE)
  r2 <- quantile(base_df[[pair[2]]], c(0.01, 0.99), na.rm = TRUE)
  g <- expand.grid(
    v1 = seq(r1[1], r1[2], length.out = n),
    v2 = seq(r2[1], r2[2], length.out = n)
  )
  names(g) <- pair
  g
}

classify_grid <- function(mod, grid_df) {
  s <- score_model(mod$method, mod$fit, prep_apply(mod$pp, grid_df))
  ifelse(s >= mod$thr, "Bad", "Good")
}

test_points <- function(pair) {
  course_data[part1 == "test", pair] |>
    mutate(actual = ifelse(course_y[part1 == "test"] == 1, "Bad", "Good")) |>
    filter(if_all(all_of(pair), \(x) !is.na(x)))
}

boundary_plot <- function(region_df, pair, title, subtitle, points = NULL) {
  p <- ggplot(region_df, aes(.data[[pair[1]]], .data[[pair[2]]])) +
    geom_raster(aes(fill = predicted), alpha = 0.45) +
    facet_wrap(~model, nrow = 2, labeller = label_wrap_gen(width = 32)) +
    labs(
      title = title,
      subtitle = subtitle,
      fill = "Predicted"
    )
  if (!is.null(points)) {
    p <- p +
      geom_point(
        data = points |> arrange(desc(actual)),
        aes(color = actual),
        size = 0.6,
        alpha = 0.7
      ) +
      labs(color = "Actual (test)")
  }
  p + coord_cartesian(expand = FALSE)
}

# (A) two-predictor models (primary partition)
plots_2pred <- list()
tuning_2pred <- list()
for (pair in pairs) {
  fit2 <- run_replicate(
    course_data,
    course_y,
    course_oracle,
    primary_split_seed,
    cfg,
    course_eng,
    methods = two_d_methods,
    num_vars = pair,
    use_sector = FALSE,
    keep_models = TRUE
  )
  tuning_2pred[[paste(pair, collapse = "_x_")]] <- fit2$tuning |>
    mutate(pair = paste(pair, collapse = " x "))
  g <- make_grid(pair, train_df)
  regions <- bind_rows(lapply(two_d_methods, \(m) {
    g |>
      mutate(
        predicted = classify_grid(fit2$models[[m]], g),
        model = sprintf(
          "%s (test AUC %.3f)",
          model_labels[[m]],
          fit2$metrics$roc_auc[fit2$metrics$model == m]
        )
      )
  }))
  plots_2pred[[paste(pair, collapse = "_x_")]] <- boundary_plot(
    regions,
    pair,
    sprintf(
      "(A) Models trained on TWO predictors only: %s and %s",
      pair[1],
      pair[2]
    ),
    "Region = full decision rule at validation-selected (Youden) threshold; points = test firms",
    points = test_points(pair)
  )
}

# (B) slices through the full 15-ratio + Sector models
true_signal_grid <- function(grid_df, truth) {
  p <- truth$params
  z_all <- sapply(ratio_vars, \(v) {
    (grid_df[[v]] - truth$center[[v]]) / truth$scale[[v]]
  })
  cap <- p$interaction_cap
  h <- pmax(0, z_all[, "EV_EBITDA"] - p$ev_threshold_z)
  drop(z_all %*% p$beta) +
    (-p$opm_penalty *
      (z_all[, "OpMargin"] < p$opm_threshold_z) -
      truth$f_centers[["f1"]]) +
    (p$interaction_gamma *
      cap *
      tanh(z_all[, "GPM"] / cap) *
      cap *
      tanh(z_all[, "AssetTurn"] / cap) -
      truth$f_centers[["f2"]]) +
    (-p$ev_lambda *
      p$ev_saturation *
      tanh(h^2 / p$ev_saturation) -
      truth$f_centers[["f3"]])
}

slice_methods <- c("logit", "logit_eng", "cart", "knn", "svm")
train_medians <- vapply(
  train_df[ratio_vars],
  \(x) median(x, na.rm = TRUE),
  numeric(1)
)
modal_sector <- names(which.max(table(train_df$Sector)))
plots_slice <- list()
for (pair in pairs) {
  g <- make_grid(pair, train_df)
  for (v in setdiff(ratio_vars, pair)) {
    g[[v]] <- train_medians[[v]]
  }
  g$Sector <- modal_sector
  # Fill = each model's risk score as a percentile within the slice (shows
  # the SHAPE of the surface even where the slice is all one class);
  # contour = that model's validation-selected decision threshold.
  slice_surface <- function(score, thr, label) {
    g[pair] |>
      mutate(
        risk_pct = percent_rank(score),
        margin = score - thr,
        model = label
      )
  }
  surfaces <- bind_rows(
    lapply(slice_methods, \(m) {
      mod <- primary$models[[m]]
      slice_surface(
        score_model(mod$method, mod$fit, prep_apply(mod$pp, g)),
        mod$thr,
        sprintf(
          "%s (test AUC %.3f)",
          model_labels[[m]],
          primary$metrics$roc_auc[primary$metrics$model == m]
        )
      )
    }),
    slice_surface(
      -true_signal_grid(g, course_truth),
      primary$models$oracle$thr,
      "TRUE DGP: Bayes risk, oracle threshold"
    )
  )
  plots_slice[[paste(pair, collapse = "_x_")]] <-
    ggplot(surfaces, aes(.data[[pair[1]]], .data[[pair[2]]])) +
    geom_raster(aes(fill = risk_pct)) +
    geom_contour(
      # Only facets whose slice actually crosses the threshold
      data = surfaces |>
        group_by(model) |>
        filter(min(margin) < 0, max(margin) > 0) |>
        ungroup(),
      aes(z = margin),
      breaks = 0,
      color = "white",
      linewidth = 0.8
    ) +
    scale_fill_viridis_c(option = "magma", labels = scales::percent) +
    facet_wrap(~model, nrow = 2, labeller = label_wrap_gen(width = 32)) +
    coord_cartesian(expand = FALSE) +
    labs(
      title = sprintf(
        "(B) Models trained on ALL 15 ratios + Sector: 2-D slice in %s and %s",
        pair[1],
        pair[2]
      ),
      subtitle = sprintf(
        paste(
          "Other ratios at training medians, Sector = %s. Fill = risk percentile within slice;",
          "white line = decision threshold (absent if the whole slice is one class).",
          "A slice, not the full rule: not comparable to (A).",
          sep = "\n"
        ),
        modal_sector
      ),
      fill = "Risk\npercentile"
    )
}

